function memoize(fn) {
  const cache = new Map();
  return (n) => {
    if (!cache.has(n)) cache.set(n, fn(n));
    return cache.get(n);
  };
}

let calls = 0;
const ways = memoize((n) => {
  calls += 1;
  return n <= 1 ? 1 : ways(n - 1) + ways(n - 2);
});

console.log(ways(10));
console.log(calls);
console.log(ways(12));
console.log(calls);
